const filtro = $('Filtrar e Extrair').first().json;
const negocio = $('Carregar Dados Negocio').first().json;
const produtos_items = $('Carregar Produtos').all();
const historico_items = $('Carregar Historico Cliente').all();

const produtos = produtos_items.map(i => i.json);
const cliente = historico_items.length > 0 ? historico_items[0].json : null;

const produtos_texto = produtos.map(p => `- ${p.nome}: R$${parseFloat(p.preco).toFixed(2)}`).join('\n');
const etapa = cliente?.etapa ?? 'inicio';
const cliente_id = cliente?.id ?? null;

return [{
  json: {
    remoteJid: filtro.remoteJid,
    pushName: filtro.pushName,
    instancia: filtro.instancia,
    mensagem: (() => {
      try {
        const unificado = $('Unificar Mensagem GAS').first().json;
        if (unificado && unificado.mensagem) return unificado.mensagem;
      } catch (e) {}
      return filtro.mensagem;
    })(),
    negocio_id: negocio.id,
    negocio_nome: negocio.nome ?? 'Gas Moura',
    nome_atendente: negocio.nome_atendente ?? 'Carol',
    horario: negocio.horario_funcionamento ?? '',
    formas_pagamento: negocio.formas_pagamento ?? '',
    taxa_entrega: negocio.taxa_entrega_descricao ?? '',
    tempo_entrega: negocio.tempo_estimado_entrega ?? '',
    boas_vindas: negocio.mensagem_boas_vindas ?? '',
    observacoes: negocio.observacoes_extras ?? '',
    produtos_texto,
    etapa,
    cliente_id
  }
}];

const dados = $('Extrair Coordenadas').first().json;
const entregadores = $input.all().map(i => i.json);

if (!entregadores || entregadores.length === 0) {
  return [{ json: { ...dados, entregador_jid: null, entregador_nome: 'Entregador', entregador_id: null, sem_entregador: true } }];
}

function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const clienteLat = parseFloat(dados.lat);
const clienteLon = parseFloat(dados.long);
const clienteGeoValido = !Number.isNaN(clienteLat) && !Number.isNaN(clienteLon);

let melhor = null;
let menorDist = Infinity;

if (!clienteGeoValido) {
  console.warn('Geocodificacao do cliente ausente/invalida (lat=' + dados.lat + ', long=' + dados.long + ') - usando primeiro entregador disponivel em vez de distancia.');
  melhor = entregadores[0];
  menorDist = null;
} else {
  for (const e of entregadores) {
    const lat = parseFloat(e.lat);
    const long = parseFloat(e.long);
    if (Number.isNaN(lat) || Number.isNaN(long)) continue;
    const dist = haversine(clienteLat, clienteLon, lat, long);
    if (dist < menorDist) { menorDist = dist; melhor = e; }
  }

  // Nenhum entregador tem lat/long ainda (nunca compartilhou localizacao ao vivo) -
  // notifica o primeiro disponivel em vez de nao notificar ninguem.
  if (!melhor) {
    melhor = entregadores[0];
    menorDist = null;
  }
}

return [{ json: { ...dados, entregador_jid: melhor.jid_whatsapp, entregador_nome: melhor.nome, entregador_id: melhor.id, distancia_km: menorDist !== null ? menorDist.toFixed(1) : null, sem_entregador: false } }];

